// src/domains/collections/services/delete-resource-permissions.ts
async function deleteResourcePermissions(input) {
	const { service, slug, kind, logger } = input;
	if (!service) return;
	try {
		const result = await service.deletePermissionsForResource(slug);
		if (result.created > 0) logger.info(`Deleted ${result.created} permission(s) for ${kind} "${slug}"`);
		if (result.skipped > 0) logger.warn(`${result.skipped} permission(s) for "${slug}" could not be deleted (may be assigned to roles)`);
	} catch (error) {
		logger.warn(`Failed to cleanup permissions for ${kind} "${slug}": ${error instanceof Error ? error.message : String(error)}`);
	}
}
export { deleteResourcePermissions };
